typedef unsigned char u_char;
typedef unsigned int u_int;

struct nglDebugStruct
{
  u_char ShowPerfInfo;
  u_char ScreenShot;
  u_char DisableQuads;
  u_char DisableMeshes;
  u_char DisableTextures;
  u_char DisableMipmaps;
  u_char DisableVSync;
  u_char DisableScratch;
  u_char DisableMipOpt;
  u_char DebugPrints;
  u_char DumpFrameLog;
  u_char DumpSceneFile;
  u_char DumpTextures;
  u_char DrawLightSpheres;
  u_char DrawMeshSpheres;
  u_char DrawNormals;
  u_char DrawAsPoints;
  u_char DrawAsLines;
  u_char VUClearMem;
  u_char VUClearRegs;
  u_char VUDebugBreak;
  u_char VUParticleDebugBreak;
  u_char DMARepeatMode;
  u_char DrawToFrontBuffer;
  u_char SyncRender;
};

struct nglScene
{
  char Pad[1180];
  float AnimTime;
};

struct nglPerfInfoStruct
{
  float FPS;
  u_int RenderStart, RenderFinish;
  float TotalMS, RenderMS, FrameMS, ListSendMS;
  u_int ParticleCount, ListSendCycles, ListSendMisses;
  float TotalSeconds;
  u_int TotalPolys, TotalVerts, TextureDataStreamed;
  u_int BakedTextureDMASize, BakedMaterialDMASize;
  u_int ListWorkBytesUsed, Vif1WorkBytesUsed, GifWorkBytesUsed, ScratchMeshBytesUsed;
  u_int MaxListWorkBytesUsed, MaxVif1WorkBytesUsed, MaxGifWorkBytesUsed, MaxScratchMeshBytesUsed;
};

struct nglQuadVertex
{
  float X, Y, U, V;
  u_int Color;
};

struct nglQuad
{
  nglQuadVertex Verts[4];
  float Z;
  u_int MapFlags;
  u_int BlendMode;
  u_int BlendModeConstant;
  void* Tex;
};

struct nglFont;
struct nglSortInfo;
struct nglLightContext;
struct nglMesh;

extern u_int nglListInitCount;
extern u_char* nglListWork;
extern u_char* nglListWorkPos;
extern u_char* nglScratchMeshWork;
extern u_char* nglScratchMeshWorkA;
extern u_char* nglScratchMeshWorkB;
extern u_int* nglScratchMeshPos;
extern nglMesh* nglScratch;
extern nglLightContext* nglGlobalLightContext;
extern nglDebugStruct nglSyncDebug;
extern nglDebugStruct nglDebug;
extern nglScene* nglCurScene;
extern nglScene nglDefaultScene;
extern u_int nglVBlankCount;
extern u_int nglDMATimeoutCounter;
extern nglFont* nglSysFont;
extern bool nglInScene;
extern nglPerfInfoStruct nglPerfInfo;
extern u_int nglNodeCount;

nglLightContext* nglCreateLightContext();
void nglListBeginScene(nglSortInfo* SortInfo = 0);
int nglGetScreenWidth();
void nglGetStringDimensions(nglFont* Font, u_int* Width, u_int* Height, const char* Text, ...);
void nglInitQuad(nglQuad* Quad);
void nglSetQuadRect(nglQuad* Quad, float x1, float y1, float x2, float y2);
void nglSetQuadColor(nglQuad* Quad, u_int Color);
void nglSetQuadZ(nglQuad* Quad, float Z);
void nglListAddQuad(nglQuad* Quad);
void nglListAddString(nglFont* Font, float x, float y, double z, const char* Text, ...);
void nglSceneDumpStart();
void nglDumpTextures();
void nglPrintf(const char* Format, ...);

#define DEBUG_ENABLE(x) 0
#define NGL_RGBA32(r,g,b,a) (((a) << 24) | ((b) << 16) | ((g) << 8) | (r))
#define NGL_VERSION ""

__asm__(".equ nglListInitCount,0x004AC04C");
__asm__(".equ nglListWork,0x004AB7CC");
__asm__(".equ nglListWorkPos,0x004AB7D0");
__asm__(".equ nglScratchMeshWorkA,0x004AB7A0");
__asm__(".equ nglScratchMeshWorkB,0x004AB7A4");
__asm__(".equ nglScratchMeshPos,0x004AB7A8");
__asm__(".equ nglScratchMeshWork,0x004AB7AC");
__asm__(".equ nglScratch,0x004AB7B0");
__asm__(".equ nglGlobalLightContext,0x004AC054");
__asm__(".equ nglSyncDebug,0x004AC9F8");
__asm__(".equ nglDebug,0x004AC9D8");
__asm__(".equ nglCurScene,0x004ABD04");
__asm__(".equ nglDefaultScene,0x004AB850");
__asm__(".equ nglVBlankCount,0x004ABFBC");
__asm__(".equ nglDMATimeoutCounter,0x004AB810");
__asm__(".equ nglSysFont,0x004AB828");
__asm__(".equ nglInScene,0x004ABD00");
__asm__(".equ nglCreateLightContext__Fv,0x0039A7F0");
__asm__(".equ nglListBeginScene__FP11nglSortInfo,0x00399560");
__asm__(".equ nglGetScreenWidth__Fv,0x00395D88");
__asm__(".equ nglGetStringDimensions__FP7nglFontPUiT1PCce,0x003A7EC8");
__asm__(".equ nglInitQuad__FP7nglQuad,0x003A6920");
__asm__(".equ nglSetQuadRect__FP7nglQuadffff,0x003A6A68");
__asm__(".equ nglSetQuadColor__FP7nglQuadUi,0x003A69E8");
__asm__(".equ nglSetQuadZ__FP7nglQuadf,0x003A6A90");
__asm__(".equ nglListAddQuad__FP7nglQuad,0x003A67F0");
__asm__(".equ nglListAddString__FP7nglFontffdPCce,0x003A7CE0");
__asm__(".equ nglSceneDumpStart__Fv,0x003AAAD8");
__asm__(".equ nglDumpTextures__Fv,0x003AAB00");

void nglListInit()
{
  ++nglListInitCount;

  // Reset the list allocator.
  nglListWorkPos = nglListWork;

  // Double buffer the scratch mesh work.
  if (nglScratchMeshWork == nglScratchMeshWorkA )
    nglScratchMeshWork = nglScratchMeshWorkB;
  else
    nglScratchMeshWork = nglScratchMeshWorkA;
  nglScratchMeshPos = (u_int*)( (u_int)nglScratchMeshWork );
  nglScratch = 0;

  // Reset the light lists.
  nglGlobalLightContext = nglCreateLightContext();

  if ( nglSyncDebug.DumpFrameLog )
    nglDebug.DumpFrameLog = 0;

  if ( nglSyncDebug.DumpSceneFile )
    nglDebug.DumpSceneFile = 0;

  if ( nglSyncDebug.DumpTextures )
    nglDebug.DumpTextures = 0;

  nglSyncDebug = nglDebug;

  // Set up the initial scene.
  nglCurScene = 0;
  nglListBeginScene();

  // Init default animation time.
  nglDefaultScene.AnimTime = nglVBlankCount * ( 1.0f / 60.0f );

  // Show performance info from the previous render list.
  if ( DEBUG_ENABLE( ShowPerfInfo ) )
  {
    nglQuad q;
    nglInitQuad( &q );
    nglSetQuadRect( &q, nglGetScreenWidth() - 230, 10, nglGetScreenWidth() - 10, 222 );
    nglSetQuadColor( &q, NGL_RGBA32( 0, 0, 0, 192 ) );
    nglSetQuadZ( &q, 0.3f );
    nglListAddQuad( &q );

    nglListAddString( nglSysFont, nglGetScreenWidth() - 220, 20, 0,
			"\1[802020FF]\2[1.1]NGL " NGL_VERSION "\2[1]\1[FFFFFFFF]\n"
			"%.2f FPS\n"
      "%.2fms ASYNC RENDER\n"
      "%.2fms DMA BUILD\n"
      "%d VERTS\n"
      "%d POLYS\n"
      "%d TEX UPLOAD\n"
      "%d NODES\n"
      "LIST  %07d %07d\n"
      "VIF1  %07d %07d\n"
      "GIF   %07d %07d\n"
      "SMESH %07d %07d\n",
      nglPerfInfo.FPS,
      nglPerfInfo.RenderMS,
      nglPerfInfo.ListSendMS,
      nglPerfInfo.TotalVerts,
      nglPerfInfo.TotalPolys,
      nglPerfInfo.TextureDataStreamed,
      nglNodeCount,
      nglPerfInfo.ListWorkBytesUsed, nglPerfInfo.MaxListWorkBytesUsed,
      nglPerfInfo.Vif1WorkBytesUsed, nglPerfInfo.MaxVif1WorkBytesUsed,
      nglPerfInfo.GifWorkBytesUsed, nglPerfInfo.MaxGifWorkBytesUsed,
      nglPerfInfo.ScratchMeshBytesUsed, nglPerfInfo.MaxScratchMeshBytesUsed );
  }

  // If we suffered a DMA timeout, print a message to that effect.
  if ( nglDMATimeoutCounter > 0 )
  {
    u_int Alpha = nglDMATimeoutCounter > 30 ? 0xFF : nglDMATimeoutCounter * 0xFF / 30;

    const char* Text = "[NGL] Vif1 DMA Timeout";
    u_int Width, Height;
    nglGetStringDimensions( nglSysFont, &Width, &Height, Text );

    int Left = nglGetScreenWidth()/2 - (Width+10)/2;

    nglQuad q;
    nglInitQuad( &q );
    nglSetQuadRect( &q, Left, 15, Left + Width + 10, 20 + Height + 5);
    nglSetQuadColor( &q, NGL_RGBA32( 0, 0, 0, Alpha ) );
    nglSetQuadZ( &q, 0.3f );
    nglListAddQuad( &q );

    nglListAddString( nglSysFont, Left + 5, 20, 0, Text );

    nglDMATimeoutCounter--;
  }

  if ( DEBUG_ENABLE( DumpFrameLog ) )
    nglPrintf( "LOG: ============================= Frame log start ===========================\n" );

  nglSceneDumpStart();

  if ( nglSyncDebug.DumpTextures )
    nglDumpTextures();

  nglInScene = true;
}
